/** url is short for the two big sources: w:<hash path>/<file> is Commons' 1920-wide copy, c:<accession> is Cleveland's print size */
export function cloudUrl (w: Wallpaper): string {
	const u = w.url;
	if (!u) return `https://i.redd.it/${w.id}.${w.ext === 'j' ? 'jpeg' : 'png'}`;
	if (u.indexOf('w:') === 0) { const file = u.slice(u.lastIndexOf('/') + 1); return `https://thumb.wikimedia.org/wikipedia/commons/thumb/${u.slice(2)}/1920px-${file}`; }
	if (u.indexOf('c:') === 0) return `https://openaccess-cdn.clevelandart.org/${u.slice(2)}/${u.slice(2)}_print.jpg`;
	return 'https://' + u;
}

